/**
 * "Blocked by" links between issues. A row reads "`issue_id` is blocked by `blocker_id`".
 */
import { and, eq } from "drizzle-orm";
import { getDb, issueDependencies } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId, brandStamp } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { IssueDependency } from "@/types/issue";
import type { IssueDependencyRow } from "@/server/db/schema/issues";

function toDependency(row: IssueDependencyRow): IssueDependency {
  return {
    orgId: brandId<OrgId>(row.orgId),
    issueId: brandId<IssueId>(row.issueId),
    blockerId: brandId<IssueId>(row.blockerId),
    createdBy: brandId<UserId>(row.createdBy),
    createdAt: brandStamp(row.createdAt),
  };
}

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toDependency(row) : null;
}

export async function insertDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
  createdBy: UserId,
): Promise<IssueDependency> {
  const row = {
    orgId,
    issueId,
    blockerId,
    createdBy,
    createdAt: toIsoTimestamp(new Date()),
  };
  getDb().insert(issueDependencies).values(row).run();
  return toDependency(row);
}

/** Resolves `true` when a link was removed. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const result = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .run();
  return result.changes > 0;
}

/** Ids of the issues blocking `issueId`. */
export async function listBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  return getDb()
    .select({ id: issueDependencies.blockerId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
      ),
    )
    .all()
    .map((row) => brandId<IssueId>(row.id));
}

/** Ids of the issues `blockerId` blocks. */
export async function listBlockedIds(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly IssueId[]> {
  return getDb()
    .select({ id: issueDependencies.issueId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .all()
    .map((row) => brandId<IssueId>(row.id));
}
