/**
 * "Blocked by" links: recording them, the completion gate and the unblocked notification.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, subscribe
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { notify } from "./notification-service";
import { issueResource, requireFound } from "./_support";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";

/** Raised when an issue with open blockers is moved to `done`. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: IssueId,
    readonly blockerIds: readonly IssueId[],
  ) {
    super(`Issue ${issueId} is blocked by ${blockerIds.join(", ")}`);
    this.name = "IssueBlockedError";
  }
}

export interface BlockerLinkInput {
  orgId: OrgId;
  issueId: IssueId;
  blockerId: IssueId;
}

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

function isOpen(issue: Issue): boolean {
  return issue.archivedAt === null && !isClosedStatus(issue.status);
}

async function loadIssue(orgId: OrgId, issueId: IssueId): Promise<Issue> {
  return requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
}

/** Ids of the open blockers of `issueId`. */
export async function listOpenBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const open: IssueId[] = [];
  for (const id of await dependencyRepo.listBlockerIds(orgId, issueId)) {
    const blocker = await issueRepo.findIssueById(orgId, id);
    if (blocker && isOpen(blocker)) open.push(id);
  }
  return open;
}

/** Throws `IssueBlockedError` when moving `issueId` to `status` is gated. */
export async function assertCanTransition(
  orgId: OrgId,
  issueId: IssueId,
  status: IssueStatus,
): Promise<void> {
  if (status !== "done") return;
  const open = await listOpenBlockerIds(orgId, issueId);
  if (open.length > 0) throw new IssueBlockedError(issueId, open);
}

/** True when `from` can reach `to` by following "blocked by" links. */
async function reaches(
  orgId: OrgId,
  from: IssueId,
  to: IssueId,
): Promise<boolean> {
  const seen = new Set<IssueId>([from]);
  const stack: IssueId[] = [from];
  while (stack.length > 0) {
    const current = stack.pop()!;
    if (current === to) return true;
    for (const next of await dependencyRepo.listBlockerIds(orgId, current)) {
      if (!seen.has(next)) {
        seen.add(next);
        stack.push(next);
      }
    }
  }
  return false;
}

export async function addBlocker(
  actor: Actor,
  input: BlockerLinkInput,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = await loadIssue(input.orgId, input.issueId);
  const blocker = await loadIssue(input.orgId, input.blockerId);
  assertCan(actor, "issue:update", issueResource(issue));

  if (issue.id === blocker.id) {
    throw new Error(`Issue ${issue.id} cannot block itself`);
  }
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    issue.id,
    blocker.id,
  );
  if (existing) return existing;

  if (await reaches(input.orgId, blocker.id, issue.id)) {
    throw new Error(
      `Blocking ${issue.id} by ${blocker.id} would create a dependency cycle`,
    );
  }

  return dependencyRepo.insertDependency(
    input.orgId,
    issue.id,
    blocker.id,
    actor.userId,
  );
}

export async function removeBlocker(
  actor: Actor,
  input: BlockerLinkInput,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);
  const issue = await loadIssue(input.orgId, input.issueId);
  assertCan(actor, "issue:update", issueResource(issue));
  return dependencyRepo.deleteDependency(
    input.orgId,
    issue.id,
    input.blockerId,
  );
}

export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);
  const issue = await loadIssue(orgId, issueId);
  assertCan(actor, "issue:read", issueResource(issue));

  const blockers: Issue[] = [];
  for (const id of await dependencyRepo.listBlockerIds(orgId, issue.id)) {
    const blocker = await issueRepo.findIssueById(orgId, id);
    if (blocker && blocker.archivedAt === null) blockers.push(blocker);
  }
  return blockers.sort((a, b) => a.number - b.number);
}

/** Notifies assignees of issues that `blockerId` closing has fully unblocked. */
async function notifyUnblocked(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  for (const id of await dependencyRepo.listBlockedIds(orgId, blockerId)) {
    const blocked = await issueRepo.findIssueById(orgId, id);
    if (!blocked || !isOpen(blocked) || blocked.assigneeId === null) continue;
    if ((await listOpenBlockerIds(orgId, blocked.id)).length > 0) continue;

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "Your issue is unblocked",
      body: `Issue ${blocked.id} has no open blockers left`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}

export function registerDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      const blocker = await issueRepo.findIssueById(
        payload.orgId,
        payload.issueId,
      );
      if (!blocker || isClosedStatus(blocker.status)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
  ];
  return () => {
    for (const off of offs) off();
  };
}
EOF
